-- Frozen PostgreSQL baseline at B3. Future schema changes require new versions.
-- Existing tables are adopted; incompatible existing columns/indexes fail safely.
-- +goose Up
CREATE TABLE IF NOT EXISTS "users" ("id" uuid,"name" text NOT NULL,"email" text NOT NULL,"password_hash" text DEFAULT '',"role" varchar(20) NOT NULL DEFAULT 'passenger',"is_active" boolean DEFAULT true,"status" text NOT NULL DEFAULT 'active',"suspended_until" timestamptz,"phone" text,"phone_verified_at" timestamptz,"deleted_at" timestamptz,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_users_status" ON "users" ("status");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_users_email" ON "users" ("email");
CREATE TABLE IF NOT EXISTS "driver_profiles" ("profile_picture_key" text,"user_id" uuid,"licence_number" text,"vehicle_card_number" text,"plate_number" text,"licence_image_url" text,"profile_picture_url" text,"verification_status" text NOT NULL DEFAULT 'pending_documents',"assigned_to" uuid,"assigned_at" timestamptz,"is_online" boolean NOT NULL DEFAULT false,"average_rating" decimal DEFAULT 0,"total_ratings" bigint DEFAULT 0,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("user_id"));
CREATE INDEX IF NOT EXISTS "idx_driver_profiles_assigned_to" ON "driver_profiles" ("assigned_to");
CREATE INDEX IF NOT EXISTS "idx_driver_profiles_verification_status" ON "driver_profiles" ("verification_status");
CREATE TABLE IF NOT EXISTS "passenger_profiles" ("profile_picture_key" text,"user_id" uuid,"full_name" text,"profile_picture_url" text,"phone" text,"average_rating" decimal DEFAULT 0,"total_ratings" bigint DEFAULT 0,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("user_id"));
CREATE TABLE IF NOT EXISTS "ratings" ("id" uuid,"from_user_id" uuid NOT NULL,"to_user_id" uuid NOT NULL,"score" bigint NOT NULL,"comment" text,"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ratings_to_user_id" ON "ratings" ("to_user_id");
CREATE INDEX IF NOT EXISTS "idx_ratings_from_user_id" ON "ratings" ("from_user_id");
CREATE TABLE IF NOT EXISTS "staff_users" ("id" uuid,"name" text NOT NULL,"email" text NOT NULL,"password_hash" text NOT NULL,"role" varchar(20) NOT NULL,"is_active" boolean NOT NULL DEFAULT true,"must_change_password" boolean NOT NULL,"failed_attempts" bigint NOT NULL DEFAULT 0,"locked_until" timestamptz,"last_login_at" timestamptz,"totp_secret_enc" text,"totp_enabled" boolean NOT NULL DEFAULT false,"created_by" uuid,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_staff_users_locked_until" ON "staff_users" ("locked_until");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_staff_users_email" ON "staff_users" ("email");
CREATE TABLE IF NOT EXISTS "staff_sessions" ("id" uuid,"staff_id" uuid NOT NULL,"token_hash" varchar(64) NOT NULL,"family_id" uuid NOT NULL,"user_agent" text,"ip" text,"expires_at" timestamptz NOT NULL,"revoked_at" timestamptz,"replaced_by" uuid,"created_at" timestamptz,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_staff_sessions_revoked_at" ON "staff_sessions" ("revoked_at");
CREATE INDEX IF NOT EXISTS "idx_staff_sessions_expires_at" ON "staff_sessions" ("expires_at");
CREATE INDEX IF NOT EXISTS "idx_staff_sessions_family_id" ON "staff_sessions" ("family_id");
CREATE INDEX IF NOT EXISTS "idx_staff_sessions_token_hash" ON "staff_sessions" ("token_hash");
CREATE INDEX IF NOT EXISTS "idx_staff_sessions_staff_id" ON "staff_sessions" ("staff_id");
CREATE TABLE IF NOT EXISTS "staff_audit_logs" ("id" uuid,"actor_id" varchar(64) NOT NULL,"action" varchar(100) NOT NULL,"target_type" varchar(50) NOT NULL,"target_id" varchar(64) NOT NULL,"ip" text,"meta" jsonb,"created_at" timestamptz,PRIMARY KEY ("id"));
