CREATE TABLE IF NOT EXISTS "driver_documents" ("object_key" text,"staging_object_key" text,"content_type" text,"expected_size" bigint,"upload_expires_at" timestamptz,"id" uuid,"driver_id" uuid NOT NULL,"type" text NOT NULL,"file_path" text NOT NULL,"file_url" text,"status" text NOT NULL DEFAULT 'submitted',"is_current" boolean NOT NULL,"rejection_code" text,"rejection_note" text,"expires_at" timestamptz,"reviewed_by" uuid,"reviewed_at" timestamptz,"created_at" timestamptz,PRIMARY KEY ("id"));
