CREATE INDEX IF NOT EXISTS "idx_driver_notifications_driver_id" ON "driver_notifications" ("driver_id");
CREATE TABLE IF NOT EXISTS "user_status_events" ("id" uuid,"user_id" uuid NOT NULL,"actor_id" uuid,"from_status" text,"to_status" text,"reason" text,"until" timestamptz,"created_at" timestamptz,PRIMARY KEY ("id"));
