CREATE TABLE IF NOT EXISTS "referrals" ("id" uuid,"referrer_id" uuid NOT NULL,"referee_id" uuid NOT NULL,"status" text NOT NULL,"reject_reason" text,"qualifying_ride_id" uuid,"referrer_reward_status" text,"created_at" timestamptz,"updated_at" timestamptz,PRIMARY KEY ("id"));
